function setupFilter(id,categories,display){const container=$(id);categories.forEach((c,i)=>{const b=document.createElement('button');b.textContent=c;b.setAttribute('aria-pressed',i===0);b.onclick=()=>{container.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));display(c)};container.appendChild(b)});display(categories[0])}setupFilter('#product-tabs',['Todos',...new Set(PRODUCTS.map(p=>p.category))],c=>{$('#menu-products').innerHTML=PRODUCTS.filter(p=>c==='Todos'||p.category===c).map(card).join('');bindWhatsApp()});const galleryData=['Bolos','Doces','Personalizados','Festas','Eventos','Bolos'];setupFilter('#gallery-tabs',['Todos','Bolos','Doces','Personalizados','Festas','Eventos'],c=>{$('#gallery-items').innerHTML=galleryData.map((category,i)=>({category,i})).filter(g=>c==='Todos'||g.category===c).map(g=>`<button data-gallery="${g.category}" aria-label="Ampliar imagem de ${g.category}"><img src="assets/collection.jpg" alt="${g.category} — coleção ilustrativa" loading="lazy" style="object-position:${g.i*20}% center"><span>${g.category} · Coleção do atelier ↗</span></button>`).join('');$('#gallery-items').querySelectorAll('button').forEach(b=>b.onclick=()=>{const d=$('#lightbox');d.querySelector('img').src=b.querySelector('img').src;d.querySelector('img').alt=b.querySelector('img').alt;d.querySelector('p').textContent=b.dataset.gallery+' · Imagem ilustrativa';d.showModal()})});$('#lightbox .close').onclick=()=>$('#lightbox').close();$('#lightbox').onclick=e=>{if(e.target===$('#lightbox'))$('#lightbox').close()};const reviews=[['Mariana A.','O bolo era tão lindo que deu vontade de guardar. Mas o sabor… esse ficou na memória de todo mundo.'],['Camila R.','Cada detalhe deixou a nossa celebração ainda mais especial. Delicadeza e sabor em perfeita harmonia.'],['Beatriz L.','Do primeiro atendimento à última fatia, uma experiência cheia de cuidado. Já estou pensando na próxima encomenda.']];let review=0;function showReview(){const r=reviews[review];$('#review-text').textContent='“'+r[1]+'”';$('#review-name').textContent=r[0];$('#review-avatar').textContent=r[0][0];$('#review-avatar').setAttribute('aria-label','Avatar ilustrativo de '+r[0])}$('#review-prev').onclick=()=>{review=(review+reviews.length-1)%reviews.length;showReview()};$('#review-next').onclick=()=>{review=(review+1)%reviews.length;showReview()};showReview();bindWhatsApp();const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.05});document.querySelectorAll('#content section').forEach(s=>{s.classList.add('reveal');observer.observe(s)});
